 println(s"普通函数: add(3, 5) = ${add(3, 5)}")

 // 2. 柯里化函数定义
 def addCurried(x: Int)(y: Int): Int = x + y
 println(s"柯里化函数: addCurried(3)(5) = ${addCurried(3)(5)}")

 // 3. 使用柯里化创建部分应用函数
 val addThree = addCurried(3)_
