 val addFour = addCurriedVersion(4)
 println(s"使用curried方法: addFour(6) = ${addFour(6)}")

 // 6. 多参数柯里化示例
 def calculate(a: Int)(b: Int)(c: Int): Int = a * b + c
 val step1 = calculate(2)_
 val step2 = step1(3)_
 println(s"多参数柯里化: calculate(2)(3)(4) = ${calculate(2)(3)(4)}")
