 val errorLogger = logger("ERROR")_

 infoLogger("系统启动成功")(System.currentTimeMillis())
 errorLogger("数据库连接失败")(System.currentTimeMillis())

 // 场景2: 数据库查询构建器
 def query(table: String)(where: String)(limit: Int): String = 
 s"SELECT * FROM $table WHERE $where LIMIT $limit"

 val userQuery = query("users")_
 val activeUsers = userQuery("status = 'active'")_
 println(s"查询: ${activeUsers(10)}")

 // 场景3: API客户端配置
 def apiClient(baseUrl: String)(timeout: Int)(headers: Map[String, String]) = 
 (endpoint: String) => s"调用 $baseUrl/$endpoint, 超时: ${timeout}ms, 头信息: $headers"

 val githubClient = apiClient("https://api.github.com")(5000)_
 val githubWithAuth = githubClient(Map("Authorization" -> "Bearer token"))
 println(githubWithAuth("users/octocat"))

 // 场景4: 验证器工厂
 def validator(min: Int)(max: Int)(value: Int): Boolean = value >= min && value <= max

 val ageValidator = validator(18)(120)_
 val scoreValidator = validator(0)(100)_

 println(s"年龄25是否有效: ${ageValidator(25)}")
 println(s"分数85是否有效: ${scoreValidator(85)}")

 // 场景5: 货币转换器
 def currencyConverter(rate: Double)(amount: Double): Double = amount * rate

 val usdToCny = currencyConverter(7.2)_
 val eurToCny = currencyConverter(7.8)_

 println(s"100美元 = ${usdToCny(100)}人民币")
 println(s"100欧元 = ${eurToCny(100)}人民币")
