 *   - 每个处理器是独立的偏函数，职责单一
 *   - orElse 运算符优雅地表达"按优先级尝试"的处理链
 *   - 运行时可根据环境动态增删处理器（如生产环境关闭 DEBUG 处理器）
 */
object Scene02_LogPipeline {

  case class LogEntry(level: String, message: String, timestamp: Long)

