 object Config {
 // 一行：声明 Config 也是 Monoid（基于字段的 Monoid）
 given Monoid[Config] = new Monoid[Config] {
 def empty: Config = Config(Map.empty, Nil)
 def combine(x: Config, y: Config): Config =
