{"rawEvent":{"message_id":"019e15c362127f5cb5a4e9378f280257","conversation_id":"019d51e7d8c67e75a99428bfc948ab60","tool_call_id":"tooluse_pJn0eHAB9Wyo0KBaWUqeyx","document":{"file_path":"/Users/jiangdadong/CodeBuddy/scala20260403/src/main/scala/demo/part12/Scene01_MTPain.scala","sub_content":"Scene01_MTPain.scala","sub_content_event":"open_editor","sub_content_event_value":"/Users/jiangdadong/CodeBuddy/scala20260403/src/main/scala/demo/part12/Scene01_MTPain.scala","sub_content_tip":"/Users/jiangdadong/CodeBuddy/scala20260403/src/main/scala/demo/part12/Scene01_MTPain.scala","apply_content":"package demo.part12

import cats.Monad
import cats.data.{EitherT, ReaderT, StateT, WriterT}
import cats.effect.{IO, IOApp}
import cats.syntax.all.*

/**
 * ============================================================
 * Scene 01: Monad Transformer 的痛点 —— 为什么需要 cats-mtl
 *
 * 真实业务往往同时需要多种"效果能力"：
 * - 读配置 → Reader
 * - 维护状态 → State
 * - 累积日志 → Writer
 * - 短路错误 → Either
 * - 异步执行 → IO
 *
 * 传统做法：用 Monad Transformer 把它们"叠"起来：
 * type App[A] = EitherT[StateT[ReaderT[IO, Config, *], Counter, *], Err, A]
 *
 * 写业务时的 3 大痛点：
 * ① 类型签名恶心长
 * ② 每一层要用对应的 lift 才能访问（ReaderT.ask、StateT.get、EitherT.leftT...）
 * ③ 想换一层的顺序/增加一层 → 所有代码签名都要改
 *
 * cats-mtl 的答案：
 * 用 type class 抽象"拥有某种能力"，不再关心具体的 transformer 栈。
 * 业务代码写 [F[_]: Ask: Stateful: Tell: Raise]，调用方在 main 挑具体类型。
 *
 * 本场景先展示"痛点"：真实写一个 Monad Transformer 栈的业务函数。
 * Scene02/03 再展示 cats-mtl 如何优雅解决。
 * ============================================================
 */
object Scene01_MTPain extends IOApp.Simple {

 // ============================================================
 // 业务模型
 // ============================================================
 case class Config(discount: BigDecimal, minOrder: BigDecimal)
 case class Stats(processed: Int, totalAmount: BigDecimal)

 sealed trait AppError
 case object OrderTooSmall extends AppError
 case class InvalidItem(name: String) extends AppError

 // ============================================================
 // ① "手写 Monad Transformer 栈" —— 真实代码长什么样
 // 栈的顺序从外到内：EitherT → StateT → ReaderT → IO
 // 读法："先跑 IO，注入 Config，维护 Stats 状态，允许抛 AppError"
 // ============================================================
 type Stack0[A] = ReaderT[IO, Config, A] // 最内层：IO + 读 Config
 type Stack1[A] = StateT[Stack0, Stats, A] // + 状态
 type App[A] = EitherT[Stack1, AppError, A] // + 错误

 // ============================================================
 // ② 在这个栈里写业务 —— 注意每个能力要用"对应的 lift"
 // ============================================================

 // 读配置（在 ReaderT 那一层）
 val readConfig: App[Config] =
 EitherT.liftF(StateT.liftF(ReaderT.ask[IO, Config]))

 // 读状态（在 StateT 那一层）
 val readStats: App[Stats] =
 EitherT.liftF(StateT.get[Stack0, Stats])

 // 更新状态
 def updateStats(f: Stats => Stats): App[Unit] =
 EitherT.liftF(StateT.modify[Stack0, Stats](f))

 // 打日志（IO 层，需要穿透 3 层）
 def log(msg: String): App[Unit] =
 EitherT.liftF(StateT.liftF(ReaderT.liftF(IO.println(s" [log] $msg"))))

 // 抛错误
 def raise[A](err: AppError): App[A] =
 EitherT.leftT[Stack1, A](err)

 // ============================================================
 // ③ 业务函数：处理一笔订单
 // 看看这段"本应很简单"的业务，夹杂了多少 lift 噪音
 // ============================================================
 def processOrder(name: String, amount: BigDecimal): App[BigDecimal] = for {
 cfg <- readConfig
 _ <- log(s"处理订单 $name 金额=$amount 最低=${cfg.minOrder}")

 // 校验
 _ <- if (name.isEmpty) raise[Unit](InvalidItem(name))
 else if (amount < cfg.minOrder) raise[Unit](OrderTooSmall)
 else EitherT.pure[Stack1, AppError](())

 // 计算折后价
 finalAmt = amount * (BigDecimal(1) - cfg.discount)

 // 更新统计
 _ <- updateStats(s => Stats(s.processed + 1, s.totalAmount + finalAmt))
 _ <- log(s" 折后金额=$finalAmt")
 } yield finalAmt

 // ============================================================
 // ④ 运行栈：一层一层"剥"出来
 // run(...) 要分别提供 Stats 初始值 + Config，最后拿 IO[...]
 // ============================================================
 def runApp[A](app: App[A], cfg: Config, init: Stats): IO[(Stats, Either[AppError, A])] = {
 // 外 → 内：先 EitherT.value，再 StateT.run(init)，最后 ReaderT.run(cfg)
 val step1: Stack1[Either[AppError, A]] = app.value
 val step2: Stack0[(Stats, Either[AppError, A])] = step1.run(init)
 val step3: IO[(Stats, Either[AppError, A])] = step2.run(cfg)
 step3
 }

 // ============================================================
 // 演示
 // ============================================================
 override def run: IO[Unit] = {
 val cfg = Config(discount = BigDecimal("0.1"), minOrder = BigDecimal("50"))
 val init = Stats(0, BigDecimal(0))

 // 组合多笔订单
 val program: App[List[BigDecimal]] = for {
 a <- processOrder("Book", 80)
 b <- processOrder("Pencil", 100)
 // 故意塞一笔过小的，会短路
 c <- processOrder("Sticker", 10)
 } yield List(a, b, c)

 for {
 _ <- IO.println("===== Scene01: Monad Transformer 的痛点 =====")
 _ <- IO.println(s" 类型签名：App[A] = EitherT[StateT[ReaderT[IO, Config, *], Stats, *], AppError, A]\n")

 (stats, r) <- runApp(program, cfg, init)

 _ <- IO.println(s"\n 最终状态: $stats")
 _ <- IO.println(s" 最终结果: $r")

 _ <- IO.println(
 """
 | ★ 痛点总结：
 | 1. 类型签名恶心长（读写都累）
 | 2. 每个访问都要 EitherT.liftF(StateT.liftF(ReaderT.ask))... —— lift 地狱
 | 3. raise 要用 EitherT.leftT[Stack1, A]，必须知道栈顺序
 | 4. 想在 Reader 和 State 之间插一层？所有代码签名都要改
 |
 | cats-mtl 的解药：下一个 Scene 见
 |""".stripMargin)
 _ <- IO.println("===== Scene01 完成 =====")
 } yield ()
 }
}
","instruction":"我创建Scene01，演示手写Monad Transformer栈的4大痛点：长签名、lift地狱、耦合栈顺序、难扩展。","apply_mode":"apply_only"}},"timestamp":1778481624,"type":"TOOL_CALL_ARGS"}

{"rawEvent":{"message_id":"019e15c362127f5cb5a4e9378f280257","conversation_id":"019d51e7d8c67e75a99428bfc948ab60","tool_call_id":"tooluse_muS3tO3gNn0Ceascm7XxO2","document":{"file_path":"/Users/jiangdadong/CodeBuddy/scala20260403/src/main/scala/demo/part12/Scene02_CatsMtlIntro.scala","sub_content":"Scene02_CatsMtlIntro.scala","sub_content_event":"open_editor","sub_content_event_value":"/Users/jiangdadong/CodeBuddy/scala20260403/src/main/scala/demo/part12/Scene02_CatsMtlIntro.scala","sub_content_tip":"/Users/jiangdadong/CodeBuddy/scala20260403/src/main/scala/demo/part12/Scene02_CatsMtlIntro.scala","apply_content":"package demo.part12

import cats.Monad
import cats.data.{EitherT, ReaderT, StateT, WriterT}
import cats.effect.{IO, IOApp}
import cats.mtl.*
import cats.syntax.all.*

/**
 * ============================================================
 * Scene 02: cats-mtl 核心 type class 一览
 *
 * cats-mtl 把"拥有某种效果能力"抽象成 6 个核心 type class：
 *
 * ┌──────────────┬─────────────────────────────────────────┐
 * │ Type Class │ 能力 │
 * ├──────────────┼─────────────────────────────────────────┤
 * │ Ask[F, R] │ 读配置/环境（Reader） │
 * │ Local[F, R] │ Ask + 在作用域内临时修改 R（Reader） │
 * │ Tell[F, L] │ 向日志/累加器写入（Writer） │
 * │ Stateful[F, S]│ 读写状态（State） │
 * │ Raise[F, E] │ 抛错误（Either 的短路） │
 * │ Handle[F, E] │ Raise + 捕获错误 │
 * └──────────────┴─────────────────────────────────────────┘
 *
 * 有了它们之后，业务签名变成：
 *
 * def f[F[_]: Monad: Ask[*, Config]: Stateful[*, Stats]
 * : Tell[*, List[String]]: Raise[*, AppError]](...)
 * : F[...]
 *
 * ✓ 不再需要知道具体的 Monad Transformer 栈
 * ✓ 不需要手动 lift
 * ✓ 能力直接用（cfg <- Ask[F, Config].ask，不需要 liftF）
 * ✓ 换栈顺序 / 加新能力 → 业务代码零修改
 *
 * 本场景把 Scene01 的"订单处理"用 cats-mtl 重写一遍对比。
 * ============================================================
 */
object Scene02_CatsMtlIntro extends IOApp.Simple {

 // ============================================================
 // 业务模型（和 Scene01 一样）
 // ============================================================
 case class Config(discount: BigDecimal, minOrder: BigDecimal)
 case class Stats(processed: Int, totalAmount: BigDecimal)

 sealed trait AppError
 case object OrderTooSmall extends AppError
 case class InvalidItem(name: String) extends AppError

 // ============================================================
 // ① 业务函数：只声明"我需要哪些能力"，不关心具体栈
 //
 // 写法 a：用 context bound（紧凑）
 // 写法 b：用 using 参数（清晰）——这里用 b
 // ============================================================
 def processOrder[F[_]: Monad](name: String, amount: BigDecimal)(using
 ask: Ask[F, Config],
 stat: Stateful[F, Stats],
 tell: Tell[F, List[String]],
 raise: Raise[F, AppError]
 ): F[BigDecimal] = for {
 cfg <- ask.ask // ← 直接读，没 lift！
 _ <- tell.tell(List(s"处理订单 $name 金额=$amount 最低=${cfg.minOrder}"))

 // 校验
 _ <- if (name.isEmpty) raise.raise(InvalidItem(name)): F[Unit]
 else if (amount < cfg.minOrder) raise.raise(OrderTooSmall): F[Unit]
 else Monad[F].unit

 finalAmt = amount * (BigDecimal(1) - cfg.discount)

 _ <- stat.modify(s => Stats(s.processed + 1, s.totalAmount + finalAmt))
 _ <- tell.tell(List(s" 折后金额=$finalAmt"))
 } yield finalAmt

 // ============================================================
 // ② 组合：一段完整的业务程序，也是泛型
 // ============================================================
 def program[F[_]: Monad](using
 Ask[F, Config], Stateful[F, Stats], Tell[F, List[String]], Raise[F, AppError]
 ): F[List[BigDecimal]] = for {
 a <- processOrder("Book", BigDecimal(80))
 b <- processOrder("Pencil", BigDecimal(100))
 c <- processOrder("Sticker", BigDecimal(10)) // 会短路
 } yield List(a, b, c)

 // ============================================================
 // ③ 在 main 里"装配"：挑一个具体的栈
 // 这里用：EitherT[WriterT[StateT[ReaderT[IO,Config,*], Stats, *], List[String], *], AppError, *]
 // 关键：cats-mtl 已经为这些 transformer 预装了 Ask/Stateful/Tell/Raise 的 given 实例
 // ============================================================
 type R[A] = ReaderT[IO, Config, A]
 type S[A] = StateT[R, Stats, A]
 type W[A] = WriterT[S, List[String], A]
 type App[A] = EitherT[W, AppError, A]

 def runApp[A](app: App[A], cfg: Config, init: Stats): IO[(Stats, List[String], Either[AppError, A])] = {
 // 从外向内"剥皮"
 val step1: W[Either[AppError, A]] = app.value
 val step2: S[(List[String], Either[AppError, A])] = step1.run
 val step3: R[(Stats, (List[String], Either[AppError, A]))] = step2.run(init)
 val step4: IO[(Stats, (List[String], Either[AppError, A]))] = step3.run(cfg)
 step4.map { case (s, (logs, r)) => (s, logs, r) }
 }

 // ============================================================
 // ④ 演示
 // ============================================================
 override def run: IO[Unit] = {
 val cfg = Config(discount = BigDecimal("0.1"), minOrder = BigDecimal("50"))
 val init = Stats(0, BigDecimal(0))

 // 关键魔法：program[App] —— 编译器自动找到 App 对应的 Ask/Stateful/Tell/Raise 实例
 val app: App[List[BigDecimal]] = program[App]

 for {
 _ <- IO.println("===== Scene02: cats-mtl 优雅解法 =====\n")
 _ <- IO.println(" 业务签名（无栈，纯 type class）：")
 _ <- IO.println(" def processOrder[F[_]: Monad](name, amount)(using")
 _ <- IO.println(" Ask[F, Config], Stateful[F, Stats],")
 _ <- IO.println(" Tell[F, List[String]], Raise[F, AppError]): F[BigDecimal]\n")

 (stats, logs, res) <- runApp(app, cfg, init)

 _ <- IO.println(" 收集到的日志：")
 _ <- logs.traverse(s => IO.println(s" $s"))
 _ <- IO.println(s"\n 最终状态: $stats")
 _ <- IO.println(s" 最终结果: $res")

 _ <- IO.println(
 """
 | ★ 和 Scene01 对比：
 | 1. processOrder 内部干干净净，没有 lift / EitherT.leftT / StateT.liftF
 | 2. 能力声明直接跟在 [F[_]] 后面，类型签名一目了然
 | 3. 想加"审计"能力？在 using 里加一个 Tell[F, AuditEvent] 即可
 | 4. 想把 WriterT 换成 IORef[List]？只改 runApp，业务零修改
 |""".stripMargin)
 _ <- IO.println("===== Scene02 完成 =====")
 } yield ()
 }
}
","instruction":"我创建Scene02，演示用cats-mtl的Ask/Stateful/Tell/Raise重写订单业务，对比Scene01痛点。","apply_mode":"apply_only"}},"timestamp":1778481662,"type":"TOOL_CALL_ARGS"}

{"rawEvent":{"message_id":"019e15c362127f5cb5a4e9378f280257","conversation_id":"019d51e7d8c67e75a99428bfc948ab60","tool_call_id":"tooluse_imq1XsAz9MU1WGpsWSeiZz","document":{"file_path":"/Users/jiangdadong/CodeBuddy/scala20260403/src/main/scala/demo/part12/Scene03_TwoInterpreters.scala","sub_content":"Scene03_TwoInterpreters.scala","sub_content_event":"open_editor","sub_content_event_value":"/Users/jiangdadong/CodeBuddy/scala20260403/src/main/scala/demo/part12/Scene03_TwoInterpreters.scala","sub_content_tip":"/Users/jiangdadong/CodeBuddy/scala20260403/src/main/scala/demo/part12/Scene03_TwoInterpreters.scala","apply_content":"package demo.part12

import cats.Monad
import cats.data.{Chain, EitherT, Kleisli, ReaderT, StateT, WriterT}
import cats.effect.{IO, IOApp, Ref}
import cats.mtl.*
import cats.syntax.all.*

/**
 * ============================================================
 * Scene 03: cats-mtl 工业实战 —— 同一业务，两套 Interpreter
 *
 * 业务：用户下单 → 校验 → 应用折扣 → 更新库存 → 落流水
 * 涉及的能力：
 * - Ask[F, AppConfig] 读全局配置
 * - Stateful[F, Inventory] 维护库存
 * - Tell[F, Chain[Event]] 追加事件流水
 * - Raise[F, DomainError] 业务错误短路
 * - Monad（for-comprehension 基础）
 *
 * Interpreter A —— 教学型：Monad Transformer 栈
 * EitherT[WriterT[StateT[Kleisli[IO, AppConfig, *], Inventory, *], Chain[Event], *], DomainError, *]
 * 全部用 cats-mtl 预装的 given 实例，业务代码不变。
 *
 * Interpreter B —— 生产型：直接用 IO + Ref（零 transformer）
 * 自己实现 Ask / Stateful / Tell / Raise 的 IO-level instance。
 * 性能最好，线上更常用。
 *
 * ★ 同一个业务函数跑两套 interpreter，结果一致 —— 这才是 cats-mtl 最大价值。
 * ============================================================
 */
object Scene03_TwoInterpreters extends IOApp.Simple {

 // ============================================================
 // 业务模型
 // ============================================================
 case class AppConfig(memberDiscount: BigDecimal, vipDiscount: BigDecimal)

 case class Sku(id: String, price: BigDecimal)
 case class Inventory(stock: Map[String, Int]) {
 def decrement(sku: String, qty: Int): Option[Inventory] =
 stock.get(sku).filter(_ >= qty).map(_ - qty).map(n => Inventory(stock.updated(sku, n)))
 }

 sealed trait Event
 case class OrderPlaced(userId: String, sku: String, qty: Int, finalPrice: BigDecimal) extends Event
 case class StockChanged(sku: String, remaining: Int) extends Event

 sealed trait DomainError extends Product with Serializable
 case class OutOfStock(sku: String) extends DomainError
 case class UnknownSku(sku: String) extends DomainError
 case class BadQuantity(qty: Int) extends DomainError

 enum UserTier { case Normal, Member, Vip }

 // ============================================================
 // ① 业务函数：完全对 F 多态，只声明需要的能力
 // ============================================================
 def placeOrder[F[_]: Monad](userId: String, tier: UserTier, sku: Sku, qty: Int)(using
 ask: Ask[F, AppConfig],
 inv: Stateful[F, Inventory],
 tell: Tell[F, Chain[Event]],
 raise: Raise[F, DomainError]
 ): F[BigDecimal] = for {
 _ <- if (qty <= 0) raise.raise(BadQuantity(qty)): F[Unit] else Monad[F].unit

 cfg <- ask.ask
 inventory <- inv.get

 remaining <- inventory.stock.get(sku.id) match {
 case None => raise.raise(UnknownSku(sku.id)): F[Int]
 case Some(n) => Monad[F].pure(n)
 }
 _ <- if (remaining < qty) raise.raise(OutOfStock(sku.id)): F[Unit]
 else Monad[F].unit

 discount = tier match {
 case UserTier.Normal => BigDecimal(0)
 case UserTier.Member => cfg.memberDiscount
 case UserTier.Vip => cfg.vipDiscount
 }
 finalPrice = sku.price * BigDecimal(qty) * (BigDecimal(1) - discount)

 // 更新库存
 newInv = inventory.decrement(sku.id, qty).get // 前面已校验过库存
 _ <- inv.set(newInv)

 // 追加事件流水
 _ <- tell.tell(Chain(
 OrderPlaced(userId, sku.id, qty, finalPrice),
 StockChanged(sku.id, newInv.stock(sku.id))
 ))
 } yield finalPrice

 // ============================================================
 // ② 组合出一段"完整业务"（两笔成功 + 一笔失败）
 // ============================================================
 def program[F[_]: Monad](using
 Ask[F, AppConfig], Stateful[F, Inventory], Tell[F, Chain[Event]], Raise[F, DomainError]
 ): F[List[BigDecimal]] = for {
 a <- placeOrder("U001", UserTier.Member, Sku("SKU-A", BigDecimal(100)), 2)
 b <- placeOrder("U002", UserTier.Vip, Sku("SKU-B", BigDecimal(50)), 3)
 // 库存是 5，再买 10 会 OutOfStock → 短路
 c <- placeOrder("U003", UserTier.Normal, Sku("SKU-A", BigDecimal(100)), 10)
 } yield List(a, b, c)

 // ============================================================
 // ③ Interpreter A：Monad Transformer 栈 + cats-mtl 预装 given
 // ============================================================
 object InterpreterA {
 type R[A] = Kleisli[IO, AppConfig, A]
 type S[A] = StateT[R, Inventory, A]
 type W[A] = WriterT[S, Chain[Event], A]
 type App[A] = EitherT[W, DomainError, A]

 def run[A](
 app: App[A], cfg: AppConfig, init: Inventory
 ): IO[(Inventory, Chain[Event], Either[DomainError, A])] = {
 val s1: W[Either[DomainError, A]] = app.value
 val s2: S[(Chain[Event], Either[DomainError, A])] = s1.run
 val s3: R[(Inventory, (Chain[Event], Either[DomainError, A]))] = s2.run(init)
 s3.run(cfg).map { case (inv, (evts, res)) => (inv, evts, res) }
 }
 }

 // ============================================================
 // ④ Interpreter B：IO + Ref —— 手写 4 个 cats-mtl instance
 //
 // 生产环境通常这样：不用 transformer，性能和调试都更好。
 // 只要 F = IO 时提供 Ask/Stateful/Tell/Raise 的 given 即可。
 // ============================================================
 object InterpreterB {

 // Raise：短路用 IO.raiseError + 我们的自定义异常包装器
 private case class DomainErr(err: DomainError) extends RuntimeException(err.toString)

 given raiseIO: Raise[IO, DomainError] with {
 def functor = cats.Functor[IO]
 def raise[E2 <: DomainError, A](e: E2): IO[A] = IO.raiseError(DomainErr(e))
 }

 // 构造器：需要 cfg + 两个 Ref 才能 wire 所有 given
 def make(
 cfg: AppConfig,
 inventoryRef: Ref[IO, Inventory],
 eventsRef: Ref[IO, Chain[Event]]
 ): (Ask[IO, AppConfig], Stateful[IO, Inventory], Tell[IO, Chain[Event]]) = {
 val ask = new Ask[IO, AppConfig] {
 def applicative = cats.Applicative[IO]
 def ask[E2 >: AppConfig]: IO[E2] = IO.pure(cfg)
 }

 val stateful = new Stateful[IO, Inventory] {
 def monad = cats.Monad[IO]
 def get: IO[Inventory] = inventoryRef.get
 def set(s: Inventory): IO[Unit] = inventoryRef.set(s)
 }

 val tell = new Tell[IO, Chain[Event]] {
 def functor = cats.Functor[IO]
 def tell(l: Chain[Event]): IO[Unit] = eventsRef.update(_ |+| l)
 }

 (ask, stateful, tell)
 }

 def run(cfg: AppConfig, init: Inventory): IO[(Inventory, Chain[Event], Either[DomainError, List[BigDecimal]])] =
 for {
 invRef <- Ref.of[IO, Inventory](init)
 evRef <- Ref.of[IO, Chain[Event]](Chain.empty)
 wired = make(cfg, invRef, evRef)
 // 把 3 个 given 安装到作用域里
 result <- {
 given Ask[IO, AppConfig] = wired._1
 given Stateful[IO, Inventory] = wired._2
 given Tell[IO, Chain[Event]] = wired._3
 // Raise 用的是 object 里的 given
 program[IO].attempt.map {
 case Right(v) => Right(v)
 case Left(DomainErr(e)) => Left(e)
 case Left(other) => throw other // 非业务异常直接传出
 }
 }
 finalInv <- invRef.get
 finalEv <- evRef.get
 } yield (finalInv, finalEv, result)
 }

 // ============================================================
 // ⑤ 演示：两个 interpreter 跑同一个 program
 // ============================================================
 override def run: IO[Unit] = {
 val cfg = AppConfig(
 memberDiscount = BigDecimal("0.10"),
 vipDiscount = BigDecimal("0.20")
 )
 val init = Inventory(Map("SKU-A" -> 5, "SKU-B" -> 10))

 for {
 _ <- IO.println("===== Scene03: 两套 Interpreter 跑同一业务 =====\n")

 // Interpreter A
 _ <- IO.println("【Interpreter A】Monad Transformer 栈 + cats-mtl 预装 given")
 tA <- InterpreterA.run(program[InterpreterA.App], cfg, init)
 (invA, evA, resA) = tA
 _ <- IO.println(s" 结果: $resA")
 _ <- IO.println(s" 库存: $invA")
 _ <- IO.println(s" 事件(${evA.length}):")
 _ <- evA.toList.traverse(e => IO.println(s" - $e"))

 // Interpreter B
 _ <- IO.println("\n【Interpreter B】直接 IO + Ref（手写 mtl instance）")
 tB <- InterpreterB.run(cfg, init)
 (invB, evB, resB) = tB
 _ <- IO.println(s" 结果: $resB")
 _ <- IO.println(s" 库存: $invB")
 _ <- IO.println(s" 事件(${evB.length}):")
 _ <- evB.toList.traverse(e => IO.println(s" - $e"))

 // 断言：两种 Interpreter 得到完全一致的业务结果
 _ <- IO.println("\n ★ 两次运行的业务结果完全一致：")
 _ <- IO.println(s" 结果一致? ${resA == resB}")
 _ <- IO.println(s" 库存一致? ${invA == invB}")
 _ <- IO.println(s" 事件一致? ${evA.toList == evB.toList}")

 _ <- IO.println(
 """
 | ★ 关键观察：
 | 1. placeOrder / program 一行没改，跑了两种截然不同的实现
 | 2. Interpreter A 适合"快速搭原型、全部纯函数式"
 | 3. Interpreter B 适合"生产环境、关心性能和调试"
 | 4. 想加审计、tracing？在 using 里加一个能力即可
 | 5. 这就是 cats-mtl 的核心价值：让 Tagless Final 更进一步
 |""".stripMargin)
 _ <- IO.println("===== Scene03 完成 =====")
 } yield ()
 }
}
